template <typename T> class PassKey { friend T; PassKey() = default; };

class Secret {
public:
  explicit Secret(int value, PassKey<Secret>);   // public, but unusable without a key
  // internals stay private; Secret itself declares no friends
};

class SecretFactory {
public:
  Secret build() { return Secret{42, PassKey<Secret>{}}; }   // friend T: OK
};
// elsewhere: Secret s{42, PassKey<Secret>{}};   // error: the constructor is private

