template <typename... Args> class PassKey;                 // primary template

template <typename... Args> requires (sizeof...(Args) > 1)
class PassKey<Args...> {
  static_assert(pass_key_internal::PairwiseUnique<Args...>);
public:
  template <typename T> requires pass_key_internal::OneOf<T, Args...>
  PassKey(PassKey<T>) {}                    // PassKey<A> -> PassKey<A, B>
};
